-- =============================================================
-- 1. CREATE DETAIL SALES INVOICE COUNT/REVIEW TABLE (DBS_SAL_INVOICE_COUNT_DTL)
-- =============================================================
CREATE TABLE "DBS_SAL_INVOICE_COUNT_DTL" (
    "ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY 
         MINVALUE 1 MAXVALUE 9999999999999999999999999999 
         INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL,
    
    "DBS_SAL_INVOICE_ID"      NUMBER NOT NULL,               -- Foreign Key to DBS_SAL_INVOICE (ID)
    "DBS_SAL_INVOICE_DTL_ID"  NUMBER NOT NULL,               -- Foreign Key to DBS_SAL_INVOICE_DTL (ID)
    "DBS_STOCK_ITEMS_ID"      NUMBER NOT NULL,               -- Foreign Key to DBS_STOCK_ITEMS (ID)
    "USER_ID"                 NUMBER NOT NULL,               -- User performing count/review
    
    "QTY_INVOICE"             NUMBER(18,4) DEFAULT 0 NOT NULL, -- Invoice target quantity
    "QTY_COUNTED"             NUMBER(18,4) DEFAULT 0 NOT NULL, -- Counted/Reviewed quantity
    "QTY_DIFFERENCE"          NUMBER(18,4) GENERATED ALWAYS AS ("QTY_COUNTED" - "QTY_INVOICE") VIRTUAL, -- Difference
    
    "REVIEW_STATUS"           VARCHAR2(30) DEFAULT 'PENDING' NOT NULL, -- 'MATCHED', 'SHORTAGE', 'SURPLUS', 'PENDING'
    "IS_DELIVERY_REVIEWED"    NUMBER(1) DEFAULT 0 NOT NULL,    -- 0 = No, 1 = Yes
    
    "LOCATION_ID"             NUMBER,                        -- Location ID
    "NOTES"                   VARCHAR2(1000),                -- Review notes
    "COUNT_DATE"              DATE DEFAULT SYSDATE NOT NULL, -- Count timestamp
    
    "CREATED"                 DATE DEFAULT SYSDATE,
    "CREATED_BY"              VARCHAR2(255),
    "UPDATED"                 DATE,
    "UPDATED_BY"              VARCHAR2(255),
    
    CONSTRAINT "PK_DBS_SAL_INV_COUNT_DTL" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_SAL_INV_CNT_HDR" FOREIGN KEY ("DBS_SAL_INVOICE_ID") 
        REFERENCES "DBS_SAL_INVOICE" ("ID") ON DELETE CASCADE,
    CONSTRAINT "FK_SAL_INV_CNT_DTL" FOREIGN KEY ("DBS_SAL_INVOICE_DTL_ID") 
        REFERENCES "DBS_SAL_INVOICE_DTL" ("ID") ON DELETE CASCADE,
    CONSTRAINT "FK_SAL_INV_CNT_ITEM" FOREIGN KEY ("DBS_STOCK_ITEMS_ID") 
        REFERENCES "DBS_STOCK_ITEMS" ("ID") ON DELETE CASCADE,
    CONSTRAINT "CH_SAL_INV_CNT_REV" CHECK (IS_DELIVERY_REVIEWED IN (0, 1))
);

-- Indexing for high-performance queries
CREATE INDEX "IDX_SAL_INV_CNT_HDR_ID"  ON "DBS_SAL_INVOICE_COUNT_DTL" ("DBS_SAL_INVOICE_ID");
CREATE INDEX "IDX_SAL_INV_CNT_DTL_ID"  ON "DBS_SAL_INVOICE_COUNT_DTL" ("DBS_SAL_INVOICE_DTL_ID");
CREATE INDEX "IDX_SAL_INV_CNT_ITEM_ID" ON "DBS_SAL_INVOICE_COUNT_DTL" ("DBS_STOCK_ITEMS_ID");
CREATE INDEX "IDX_SAL_INV_CNT_USER_ID" ON "DBS_SAL_INVOICE_COUNT_DTL" ("USER_ID");


-- =============================================================
